```ts
/**
 * Mirrors the Rust Ord impl for Version.
 * Returns negative if a < b, positive if a > b, 0 if equal.
 */
export function compareVersions(a: Version, b: Version): number {
  // Every nullable field sorts null as greater than any non-null value.
  const cmp = <T>(x: T | null, y: T | null, order: (p: T, q: T) => number): number => {
    if (x === null || y === null) return x === y ? 0 : x === null ? 1 : -1
    return order(x, y)
  }
  const str = (x: string, y: string) => x.localeCompare(y)
  const num = (x: number, y: number) => x - y

  return (
    cmp(a.variant, b.variant, str) ||
    (a.major - b.major) ||
    cmp(a.minor, b.minor, num) ||
    cmp(a.patch, b.patch, num) ||
    cmp(a.prerelease, b.prerelease, str) ||
    cmp(a.build, b.build, str)
  )
}
```

- Noticed all five nullable fields (variant, minor, patch, prerelease, build) share the exact same "null sorts greater" rule, despite differently-worded comments in the original — collapsed them into one `cmp` helper.
- Replaced each pair of null-check `if`s plus a manual non-null comparison with a single `cmp(...)` call per field.
- Replaced the "compute diff, `if (cmp !== 0) return cmp`" pattern with `||`-chaining, relying on `0` being falsy and any nonzero diff being truthy.
- `major` (never null) stays a direct subtraction, chained the same way as the rest.

