#[cfg(not(windows))]
fn trampoline_signal(path: &std::path::Path) -> bool {
    use std::io::Read as _;

    // Ordered before the open: opening a FIFO for reading blocks forever.
    let probe = || -> std::io::Result<bool> {
        if !std::fs::metadata(path)?.is_file() {
            return Ok(false);
        }
        let mut prefix = Vec::with_capacity(TRAMPOLINE_PROBE_BYTES);
        std::fs::File::open(path)?
            .take(TRAMPOLINE_PROBE_BYTES as u64)
            .read_to_end(&mut prefix)?;
        // Second line, matched whole (bytes, not `str`) — see TRAMPOLINE_MARKER docs.
        Ok(prefix
            .split(|byte| *byte == b'\n')
            .nth(1)
            .is_some_and(|line| line == TRAMPOLINE_MARKER.as_bytes()))
    };

    probe().unwrap_or(false)
}

