fn trampoline_signal(path: &std::path::Path) -> bool {
    path.extension()
        .is_some_and(|extension| extension.eq_ignore_ascii_case("exec"))
        || std::fs::metadata(path.with_extension("exec")).is_ok_and(|sidecar| sidecar.is_file())
}
```

