    pub async fn render_toolchain(&self, request: RenderRequest<'_>) -> Result<RenderReport, PackageErrorKind> {
        let file_structure = self.file_structure();

        // Read once, at render entry, and threaded down as a parameter — never
        // re-probed per stage. Outside a gated build the variable is `None` and
        // the env var is never read at all (`subsystem-tests.md`).
        #[cfg(any(test, feature = "__testing"))]
        let fault = read_fault_hook();
        #[cfg(not(any(test, feature = "__testing")))]
        let fault: Option<String> = None;
        let fault = fault.as_deref();

        // Step 1 (module docs): a dry run performs none of the steps below,
        // and the case-fold probe is no exception (RUL-74). The probe writes
        // into the directory it judges, so even into a home root that already
        // exists it moves that directory's own mtime — a write C-049 promised
        // not to make. The unfolded name set is used instead; the residual is
        // confined to the prediction (see `RenderRequest::dry_run`).
        if request.dry_run {
            return render_with(file_structure, request, false, fault).await;
        }

        // Step 2: the home root, before the probe and before `.gitignore` —
        // preceded by RUL-44's component guard, in the same blocking unit,
        // because a symlink one level above the root relocates everything
        // below it before `ensure_home_root` gets a path to judge.
        if !prepare_home_root(request.scope, request.home.root()).await {
            return Ok(skipped_render());
        }

        // Step 3: best-effort — see `ensure_gitignore_best_effort`.
        ensure_gitignore_best_effort(request.home.root()).await;

        // Step 4: one render lock over the home, for the whole body (RUL-30).
        let Some(_render_lock) = acquire_render_lock_or_warn(file_structure, &request).await else {
            return Ok(skipped_render());
        };

        // Step 5: the probe, against the root step 2 just created.
        let Some(case_insensitive) = probe_case_insensitivity_or_warn(request.home.root()).await else {
            return Ok(skipped_render());
        };

        // Step 6: the shell directory, then `active` — in that order (C-083),
        // inside the render lock, and before any trampoline is written. See
        // `ensure_active_link` for why a failure here still lets the render
        // continue.
        ensure_active_link(request.home, fault).await?;

        render_with(file_structure, request, case_insensitive, fault).await
    }
}

/// Step 2: refuses a symlinked home, then ensures `home_root` exists
/// (RUL-33, RUL-37, RUL-44). Warns and returns `false` on any failure —
/// see [`PackageManager::render_toolchain`]'s "Failure is not an error"
/// doc section; the caller treats `false` as C-050's skip.
async fn prepare_home_root(scope: &RenderStampScope, home_root: &Path) -> bool {
    let (scope, root) = (scope.clone(), home_root.to_path_buf());
    match tokio::task::spawn_blocking(move || {
        let home = ToolchainHome::new(root);
        refuse_symlinked_home(&scope, &home)?;
        ensure_home_root(&home)
    })
    .await
    {
        Ok(Ok(_created)) => true,
        Ok(Err(error)) => {
            // Loud, not debug: unlike a read-only checkout this is either a
            // tree ocx cannot own or a committed symlink out of it (RUL-33).
            log::warn!("Skipping toolchain render: '{}' could not be prepared: {error}", home_root.display());
            false
        }
        Err(join_error) => {
            log::warn!("Skipping toolchain render: the home-root task failed: {join_error}");
            false
        }
    }
}

/// Step 3: C-004's ignore file. Best-effort — a repository that controls
/// this tree may deny it, and the trampolines are the render's product.
async fn ensure_gitignore_best_effort(home_root: &Path) {
    let home = ToolchainHome::new(home_root.to_path_buf());
    match tokio::task::spawn_blocking(move || home.ensure_gitignore()).await {
        Ok(Ok(_written)) => {}
        Ok(Err(error)) => log::warn!("Toolchain home '{}' has no ignore file: {error}", home_root.display()),
        Err(join_error) => log::warn!("The toolchain ignore-file task failed: {join_error}"),
    }
}

/// Step 4: acquires the whole-body render lock (RUL-30). A timeout is
/// C-050's skip, never an error — `None` tells the caller to degrade.
async fn acquire_render_lock_or_warn(
    file_structure: &FileStructure,
    request: &RenderRequest<'_>,
) -> Option<ocx_util::fs::LockedFile> {
    match render_lock_parameters(file_structure, request).acquire().await {
        Ok(guard) => Some(guard),
        Err(error) => {
            log::warn!(
                "Skipping toolchain render of '{}': its render lock was not available: {error}",
                request.home.root().display()
            );
            None
        }
    }
}

/// Step 5: the case-fold probe, against the root step 2 just created.
async fn probe_case_insensitivity_or_warn(home_root: &Path) -> Option<bool> {
    match filesystem_is_case_insensitive(home_root).await {
        Ok(answer) => Some(answer),
        Err(error) => {
            log::warn!(
                "Skipping toolchain render: the case-fold probe of '{}' failed: {error}",
                home_root.display()
            );
            None
        }
    }
}

/// Step 6: `shells/<shell>/` then `active`, in that order (C-083). Never an
/// early return for an ordinary failure — a home whose activation link
/// cannot be repaired still renders the rest of the tree; only the C-048
/// fault seam propagates, so [`PackageManager::render_toolchain`] returns
/// no [`RenderReport`] on that path at all.
async fn ensure_active_link(home: &ToolchainHome, fault: Option<&str>) -> Result<(), PackageErrorKind> {
    let root = home.root().to_path_buf();
    let shell_tree =
        tokio::task::spawn_blocking(move || ensure_shell_tree(&ToolchainHome::new(root), DEFAULT_SHELL)).await;

    // C-083's one interruption point between the two writes: on abort
    // `active` is **absent**, which is a lookup miss and never a wrong
    // answer — the state the reverse order could not produce.
    #[cfg(any(test, feature = "__testing"))]
    maybe_inject_fault(fault, RenderStage::AfterShellTree)?;
    #[cfg(not(any(test, feature = "__testing")))]
    let _ = fault;

    let root = home.root().to_path_buf();
    let healed = match shell_tree {
        Ok(Ok(())) => tokio::task::spawn_blocking(move || heal_active(&ToolchainHome::new(root), DEFAULT_SHELL)).await,
        other => other,
    };
    match healed {
        Ok(Ok(())) => {}
        Ok(Err(error)) => log::warn!(
            "Toolchain '{}' has no usable '{}' link: {error}",
            home.root().display(),
            home.active().display()
        ),
        Err(join_error) => log::warn!("The toolchain activation-link task failed: {join_error}"),
    }
    Ok(())
}
