    /// order: refuse a symlinked home and create the root (RUL-33, RUL-24) —
    /// before the case-fold probe and before `.gitignore` (RUL-44); acquire
    /// one `lock_scoped` over the home for the rest of the body (a timeout is
    /// a skip, never an error — C-050, RUL-30); the case-fold probe (RUL-37);
    /// heal `shells/default` then `active`, in that order (C-083, C-081),
    /// before any trampoline is written; then hand off to [`render_with`].
    ///
    /// Every early failure before the lock is acquired — home-root creation,
    /// the render lock, the case-fold probe — returns a warned, empty
    /// [`skipped_render`] rather than an error. A failure in the shell-tree /
    /// `active` heal only warns and continues: the rest of the tree still
    /// renders correctly, and a wrong `active` just withholds the prompt
    /// gate rather than exposing anything.
    ///
    /// # Errors
    ///
    /// Only ever returned by [`render_with`] — see its docs and the
    /// type-level `# Errors` section above for the full taxonomy
    /// (`PackageErrorKind::{ToolchainPath, ShimNameInvalid, Internal}`).
    pub async fn render_toolchain(&self, request: RenderRequest<'_>) -> Result<RenderReport, PackageErrorKind> {
        let file_structure = self.file_structure();

