            Ok(guard) => guard,
            Err(error) => {
                log::warn!(
                    "Skipping toolchain render of '{}': its render lock was not available: {error}",
                    root.display()
                );
                return Ok(skipped_render());
            }
        };

        let case_insensitive = match filesystem_is_case_insensitive(&root).await {
            Ok(answer) => answer,
            Err(error) => {
                log::warn!("Skipping toolchain render: the case-fold probe of '{}' failed: {error}", root.display());
