pub(crate) fn publish_by_rename(path: &Path, bytes: &[u8]) -> Result<(), Error> {
    fn io_err(path: &Path, e: std::io::Error) -> Error {
        ProjectError::new(path.to_path_buf(), ProjectErrorKind::Io(e)).into()
    }

    // `Path::parent` is `Some("")` for a bare relative filename and `None` only
    // for a root; both name the current directory, and neither reaches here
    // from a caller — every one resolves a config-file path first.
    let parent = match path.parent() {
        Some(parent) if !parent.as_os_str().is_empty() => parent,
        _ => Path::new("."),
    };
    std::fs::create_dir_all(parent).map_err(|e| io_err(parent, e))?;

    let mut tmp = tempfile::NamedTempFile::new_in(parent).map_err(|e| io_err(parent, e))?;
    tmp.write_all(bytes).map_err(|e| io_err(tmp.path(), e))?;
    carry_existing_mode(path, &tmp)?;
    tmp.as_file().sync_data().map_err(|e| io_err(tmp.path(), e))?;
    ocx_util::fs::persist_temp_file(tmp, path).map_err(|e| io_err(path, e))?;

    fsync_parent(parent)
}
```

- Extracted the repeated `ProjectError::new(<path>.to_path_buf(), ProjectErrorKind::Io(e))` construction into a local `io_err` helper.
- Replaced each of the 4 `map_err(|e| ProjectError::new(...))` closures with `map_err(|e| io_err(<path>, e))`.
- No behavior change: same error path, same wrapped path per call site, same control flow and comments.

