    async fn write_verified_object(&self, target: PathBuf, claimed_digest: &Digest, bytes: &[u8]) -> Result<()> {
        let algorithm = claimed_digest.algorithm();
        let computed = algorithm.hash(bytes);
        if &computed != claimed_digest {
            return Err(ocx_store::file_structure::error::Error::DigestMismatch {
                claimed: claimed_digest.clone(),
                computed,
            }
            .into());
        }

        // Verify-and-self-heal: re-hash any existing bytes before trusting
        // them. A zero-byte crash artifact or a tampered file both fail this
        // check and fall through to the overwrite below.
        let already_correct = tokio::fs::read(&target)
            .await
            .is_ok_and(|existing| algorithm.hash(&existing) == computed);
        if already_correct {
            return Ok(());
        }

        let parent = target
            .parent()
            .ok_or_else(|| super::error::file_error(&target, std::io::Error::other("path has no parent")))?
            .to_path_buf();
        tokio::fs::create_dir_all(&parent)
            .await
            .map_err(|e| super::error::file_error(&parent, e))?;

        let bytes_owned = bytes.to_vec();
        let target_for_blocking = target.clone();
        let claimed = claimed_digest.clone();
        let publish_result = tokio::task::spawn_blocking(move || -> std::io::Result<()> {
            let mut tmp = tempfile::NamedTempFile::new_in(&parent)?;
            std::io::Write::write_all(&mut tmp, &bytes_owned)?;
            tmp.as_file().sync_data()?;
            match ocx_util::fs::persist_temp_file(tmp, &target_for_blocking) {
                Ok(()) => Ok(()),
                Err(err) => match std::fs::read(&target_for_blocking) {
                    Ok(current) if claimed.algorithm().hash(&current) == claimed => Ok(()),
                    _ => Err(err),
                },
            }
        })
        .await
        .map_err(|join_err| super::error::file_error(&target, std::io::Error::other(join_err)))?;

        publish_result.map_err(|io_err| super::error::file_error(&target, io_err))
    }
