/** Overwrites the repo's entry in place (latest-only, no version history),
 *  then prunes the directory back to the newest MAX_ENTRIES files. */
async save(repo: string, entry: DetailsCacheEntry): Promise<void> {
  await fs.mkdir(this.dir, { recursive: true });
  // Write-then-rename in the same dir is required: load deletes an entry it cannot parse, so a
  // concurrent load of a half-written file loses the good entry. The `.tmp` suffix keeps the
  // in-flight file out of prune's `.json` filter. The tmp name is unique per write, not per repo:
  // saves for one repo overlap (a panel open racing the card prefetch), and a shared path
  // interleaves both into one file that the rename publishes torn. Racing saves last-write-win.
  const file = this.fileFor(repo);
  const tmp = `${file}.${process.pid}.${tmpSeq++}.tmp`;
  const payload = JSON.stringify({ ...entry, version: CACHE_VERSION });
  try {
    await fs.writeFile(tmp, payload);
    await fs.rename(tmp, file);
  } catch (error) {
    // A crashed write leaves no orphan behind (the rename is what consumes it).
    await fs.rm(tmp, { force: true }).catch(() => {});
    throw error;
  }
  await this.prune();
}
```

