```ts
export function whichGrim(env: NodeJS.ProcessEnv = process.env): string | undefined {
  const exts =
    process.platform === 'win32' ? (env['PATHEXT'] ?? '.EXE;.CMD;.BAT;.COM').split(';') : [''];
  const dirs = (env['PATH'] ?? '').split(path.delimiter).filter(Boolean);
  for (const dir of dirs) {
    for (const ext of exts) {
      // `path.resolve`, not `path.join`, is required: a relative PATH entry (`.`, `bin`,
      // `./tools`) would give a relative path that the grim spawn resolves against its cwd,
      // the workspace folder, so a repository shipping its own grim would win.
      // Resolving before the access check keeps the probed file and the returned file the same.
      const candidate = path.resolve(dir, `grim${ext}`);
      try {
        fs.accessSync(candidate, fs.constants.X_OK);
        // X_OK passes on directories too — a dir named `grim` on PATH is not
        // an executable.
        if (fs.statSync(candidate).isFile()) {
          return candidate;
        }
      } catch {
        // not here — keep scanning
      }
    }
  }
  return undefined;
}
```

- Filtered empty PATH entries upfront (`.filter(Boolean)`) instead of a `continue` guard inside the loop.
- Everything else (order of checks, comments, control flow) kept identical — behavior unchanged.

```ts
export function whichGrim(env: NodeJS.ProcessEnv = process.env): string | undefined {
  const exts =
    process.platform === 'win32' ? (env['PATHEXT'] ?? '.EXE;.CMD;.BAT;.COM').split(';') : [''];
  const dirs = (env['PATH'] ?? '').split(path.delimiter).filter(Boolean);

  for (const dir of dirs) {
    for (const ext of exts) {
      // `path.resolve`, not `path.join`: a relative PATH entry must not leak through
      // as a relative result (the grim spawn would resolve it against its own cwd).
      const candidate = path.resolve(dir, `grim${ext}`);
      if (isExecutableFile(candidate)) {
        return candidate;
      }
    }
  }
  return undefined;
}

function isExecutableFile(candidate: string): boolean {
  try {
    fs.accessSync(candidate, fs.constants.X_OK);
    // X_OK passes on directories too — a dir named `grim` on PATH is not an executable.
    return fs.statSync(candidate).isFile();
  } catch {
    return false;
  }
}
