```ts
export function usePackageRoot(
  ns: MaybeRefOrGetter<string>,
  pkg: MaybeRefOrGetter<string>,
  wireBase: MaybeRefOrGetter<string> = '',
) {
  const root = ref<PackageRoot | null>(null)
  const loading = ref(true)
  const error = ref<string | null>(null)
  const notFound = ref(false)

  // Monotonic request token: guards every state write below against a
  // slow, now-superseded response landing after a newer navigation already
  // fired its own fetch.
  let requestToken = 0

  onMounted(() => {
    watch(
      () => [toValue(ns), toValue(pkg), toValue(wireBase)] as const,
      async ([nsVal, pkgVal, baseVal]) => {
        const token = ++requestToken
        const stale = () => token !== requestToken
        loading.value = true
        error.value = null
        notFound.value = false
        try {
          // Alias first (ad-blocker-safe `_root.json`), canonical second —
          // see sources/mirror.ts's packageRootAliasPath.
          const base = wirePrefix(baseVal)
          let resp = await fetch(`${base}/p/${nsVal}/${pkgVal}/_root.json`)
          if (stale()) return
          if (resp.status === 404) {
            resp = await fetch(`${base}/p/${nsVal}/${pkgVal}.json`)
            if (stale()) return
          }
          if (resp.status === 404) {
            notFound.value = true
            root.value = null
            return
          }
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`)
          const data = await resp.json()
          if (stale()) return
          root.value = data
        } catch (e) {
          if (stale()) return
          error.value = e instanceof Error ? e.message : 'Failed to load package'
          root.value = null
        } finally {
          if (!stale()) loading.value = false
        }
      },
      { immediate: true },
    )
  })

  return { root, loading, error, notFound }
}
```

- Factored the repeated `token !== requestToken` check into a local `stale()` closure, used at every guard point.
- Collapsed the alias/canonical fetch into one `resp` variable reused across both attempts instead of duplicated blocks.
- Trimmed comments to their load-bearing rationale (token guard, ad-blocker alias) and dropped restated-by-code narration.
- Control flow, ordering of state writes, and every existing guard/check are unchanged — no behavior difference.

```ts
/**
 * Fetches the wire package root from the ad-blocker-safe alias
 * `<wireBase>/p/<ns>/<pkg>/_root.json` (`sources/mirror.ts`), falling back on 404 to the
 * byte-identical canonical `<wireBase>/p/<ns>/<pkg>.json`. `wireBase` is the source's mount
 * prefix, `''` for the `root: true` source and `index/<label>` otherwise (see `wirePrefix`).
 * Arguments accept refs/getters and refetch on change, post-mount only (SSR-safe); VitePress's
 * router reuses the component across package navigations, so a one-shot `onMounted` fetch would
 * leave stale data on screen. CAS asset URLs (`casUrl()`, `utils/cas.ts`) must be built from the
 * bare `ns`/`pkg` given here; `root.name` carries the `ocx.sh/` prefix, so a URL from it 404s.
 */
export function usePackageRoot(
  ns: MaybeRefOrGetter<string>,
  pkg: MaybeRefOrGetter<string>,
  wireBase: MaybeRefOrGetter<string> = '',
) {
  const root = ref<PackageRoot | null>(null)
  const loading = ref(true)
  const error = ref<string | null>(null)
  const notFound = ref(false)

  // Monotonic request token: guards every state write below against a
  // slow, now-superseded response landing after a newer navigation already
  // fired its own fetch — without this, a stale package-A response can
  // overwrite package-B's state after a quick A→B nav (URL shows B, page
  // renders A).
  let requestToken = 0

  // Alias first, canonical second. `/p/<ns>/<pkg>.json` — the wire root's
  // own URL — is BLOCKED by any browser running EasyList/EasyPrivacy when
  // the package name matches one of their ~800 unanchored `/<word>.js`
  // rules (`ocx.sh/hawkeye/hawkeye` vs EasyPrivacy's `/hawkeye.js`,
  // 2026-08-27). `sources/mirror.ts` writes `_root.json` beside every root
  // for exactly this fetch. The canonical path stays as the fallback: a
  // tree mirrored by an older build of this package has no alias.
  async function fetchRoot(nsVal: string, pkgVal: string, baseVal: string, token: number) {
    const base = wirePrefix(baseVal)
    let resp = await fetch(`${base}/p/${nsVal}/${pkgVal}/_root.json`)
    if (token !== requestToken) return
    if (resp.status === 404) {
      resp = await fetch(`${base}/p/${nsVal}/${pkgVal}.json`)
    }
    if (token !== requestToken) return
    if (resp.status === 404) {
      notFound.value = true
      root.value = null
      return
    }
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`)
    const data = await resp.json()
    if (token === requestToken) root.value = data
  }

  onMounted(() => {
    watch(
      // `wireBase` is watched alongside ns/pkg: two packages from DIFFERENT
      // sources have different mount prefixes, so dropping it here would
      // refetch package B's root under source A's prefix.
      () => [toValue(ns), toValue(pkg), toValue(wireBase)] as const,
      async ([nsVal, pkgVal, baseVal]) => {
        const token = ++requestToken
        loading.value = true
        error.value = null
        notFound.value = false
        try {
          await fetchRoot(nsVal, pkgVal, baseVal, token)
        } catch (e) {
          if (token !== requestToken) return
          error.value = e instanceof Error ? e.message : 'Failed to load package'
          root.value = null
        } finally {
          if (token === requestToken) loading.value = false
        }
      },
      { immediate: true },
    )
  })

  return { root, loading, error, notFound }
}
```

- Extracted the alias→canonical fetch/404/notFound logic into a `fetchRoot` helper, cutting the `watch` callback's nesting from 4 levels to 2.
- Kept every token check, the 404-fallback order, the `notFound` vs. `error` distinction, and the `finally`'s token-guarded `loading` reset unchanged.
- Trimmed the inline comments to their load-bearing point (why alias-first, why token-guarded) without dropping the rationale.
